(function () {
  var R = window.BLUP3TS_RARITY, D = window.BLUP3TS_DATA, F = window.BLUP3TS_FILTER;
  function share(coll, typ, val) {
    var c = R && R[coll], h = F && F.hash; if (!c || !h || typ == null || val == null) return;
    var n = c.t[h(typ)] && c.t[h(typ)][h(String(val))];
    return n ? Math.round(10000 * n / c.total) / 100 : undefined;
  }
  R.share = share;
  if (!D || !D.pets) return;
  D.pets.forEach(function (p) {
    var c = R[p.collection]; if (!c) return;
    if (p.mint && c.ranks && c.ranks[p.mint]) { p.rank = c.ranks[p.mint]; p.of = c.total; p.rankSource = 'gravemarket'; }
    (p.traits || []).forEach(function (t) {
      if (!t || t.hidden || t.slot) return;
      var sh = share(p.collection, t.type, t.value);
      if (typeof sh === 'number') t.share = sh;
    });
  });
})();
